from PIL import Image
import numpy as np
im=np.asarray(Image.open('first_frame.png').convert('RGB')).astype(float)
# inspect per-pixel line edges in right half, horizontal/vertical finite diffs > thresholds, coordinate list by y ranges
lum=im@np.array([.299,.587,.114])
dx=np.abs(np.diff(lum,axis=1));dy=np.abs(np.diff(lum,axis=0))
print('strong DX')
for y0 in range(40,144,8):
 a=[]
 for y in range(y0,min(y0+8,144)):
  xs=np.where(dx[y]>12)[0]
  for x in xs:
   if x>145:a.append((x,y,round(dx[y,x])))
 print(y0, sorted(a,key=lambda z:-z[2])[:12])
print('strong DY')
for y0 in range(40,143,8):
 a=[]
 for y in range(y0,min(y0+8,143)):
  xs=np.where(dy[y]>12)[0]
  for x in xs:
   if x>145:a.append((x,y,round(dy[y,x])))
 print(y0, sorted(a,key=lambda z:-z[2])[:12])
